"""Owner catalog clean-up, bulk export, checkbox code selection and mobile layout.

Reuses existing audited delete/archival API, without purging real data.
"""
from pathlib import Path

UI_JS = "\n/* Dono: exportação seletiva de modelos e variações. Sem gravar no banco. */\nfunction mbOpenModelExport(){\n if(!owner())return;\n let dialog=document.getElementById('mbExportModels');\n if(!dialog){dialog=document.createElement('dialog');dialog.id='mbExportModels';document.body.append(dialog)}\n const attrs=[\n  ['name','Nome do modelo'],['category','Tipo de peça'],['brand','Marca'],\n  ['barcode','Código de barras'],['extra_code','Código extra / referência'],\n  ['source_code','Código de origem'],['source_gtin','GTIN de origem'],\n  ['color','Cor'],['size','Tamanho'],['stock','Quantidade no tamanho'],\n  ['reserved_stock','Reservado'],['available_stock','Disponível'],\n  ['size_totals','Quantidade de todos os tamanhos'],['model_total','Quantidade total do modelo'],\n  ['variations','Número de variações'],['price','Preço unitário (R$)'],['photo','Fotos / links das imagens']\n ];\n const esc=v=>String(v||'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n const brands=[...new Set(products.map(p=>p.brand).filter(Boolean))].sort();\n const types=[...new Set(products.map(p=>p.category).filter(Boolean))].sort();\n const opt=list=>'<option value=\"\">Todas</option>'+list.map(v=>'<option value=\"'+esc(v)+'\">'+esc(v)+'</option>').join('');\n dialog.innerHTML='<div class=\"mb-export-header\"><div><h2>Baixar informações</h2><p>Escolha os campos e modelos. A planilha abre no Excel.</p></div><button type=\"button\" class=\"secondary\" data-export-close aria-label=\"Fechar\">✕</button></div>'+\n '<div class=\"mb-export-filters\"><label>Modelos<select id=\"mbExportScope\"><option value=\"all\">Todos os modelos ativos</option><option value=\"visible\">Pesquisa atual</option></select></label><label>Marca<select id=\"mbExportBrand\">'+opt(brands)+'</select></label><label>Tipo de peça<select id=\"mbExportType\">'+opt(types)+'</select></label></div>'+\n '<h3>Escolha o que baixar</h3><div class=\"mb-export-fields\">'+attrs.map(([k,v])=>'<label><input type=\"checkbox\" data-export-field=\"'+k+'\" '+(['source_gtin','source_code','photo'].includes(k)?'':'checked')+'><span>'+v+'</span></label>').join('')+'</div>'+\n '<div class=\"mb-export-actions\"><button type=\"button\" class=\"secondary\" data-export-all>Selecionar tudo</button><button type=\"button\" class=\"secondary\" data-export-none>Desmarcar tudo</button></div>'+\n '<label class=\"mb-export-zip\"><input type=\"checkbox\" id=\"mbExportImages\"> Incluir fotos originais em arquivo ZIP (até 100 imagens por exportação)</label>'+\n '<p class=\"sub\" id=\"mbExportProgress\" role=\"status\"></p><p class=\"mb-export-error\" id=\"mbExportError\" role=\"alert\"></p>'+\n '<div class=\"mb-export-footer\"><button type=\"button\" class=\"secondary\" data-export-close>Cancelar</button><button type=\"button\" class=\"primary\" id=\"mbExportDownload\">Baixar seleção</button></div>';\n dialog.querySelectorAll('[data-export-close]').forEach(b=>b.onclick=()=>dialog.close());\n dialog.querySelector('[data-export-all]').onclick=()=>dialog.querySelectorAll('[data-export-field]').forEach(x=>x.checked=true);\n dialog.querySelector('[data-export-none]').onclick=()=>dialog.querySelectorAll('[data-export-field]').forEach(x=>x.checked=false);\n const filename=v=>String(v||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z0-9_-]/gi,'_').slice(0,60);\n const csvCell=v=>{let x=String(v??'');if(/^[=+\\-@\\t\\r]/.test(x))x=\"'\"+x;return '\"'+x.replace(/\"/g,'\"\"')+'\"'};\n const download=(blob,name)=>{const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),20000)};\n const encoder=new TextEncoder();\n const crcTable=Uint32Array.from({length:256},(_,n)=>{let c=n;for(let i=0;i<8;i++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0});\n const crc32=data=>{let c=0xffffffff;for(const b of data)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0};\n function makeZip(files){\n  const parts=[],central=[];let offset=0,centralSize=0;\n  for(const file of files){\n   const name=encoder.encode(file.name),data=file.data,crc=crc32(data);\n   const loc=new Uint8Array(30+name.length),v=new DataView(loc.buffer);\n   v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);\n   v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);loc.set(name,30);parts.push(loc,data);\n   const entry=new Uint8Array(46+name.length),cv=new DataView(entry.buffer);\n   cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);\n   cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);entry.set(name,46);central.push(entry);centralSize+=entry.length;offset+=loc.length+data.length;\n  }\n  const end=new Uint8Array(22),dv=new DataView(end.buffer);dv.setUint32(0,0x06054b50,true);dv.setUint16(8,files.length,true);dv.setUint16(10,files.length,true);dv.setUint32(12,centralSize,true);dv.setUint32(16,offset,true);\n  return new Blob([...parts,...central,end],{type:'application/zip'});\n }\n dialog.querySelector('#mbExportDownload').onclick=async()=>{\n  const info=dialog.querySelector('#mbExportProgress'),error=dialog.querySelector('#mbExportError'),button=dialog.querySelector('#mbExportDownload');error.textContent='';info.textContent='';\n  const fields=[...dialog.querySelectorAll('[data-export-field]:checked')].map(x=>x.dataset.exportField);\n  if(!fields.length){error.textContent='Marque pelo menos um campo.';return}\n  const groupBy=new Map(),brand=dialog.querySelector('#mbExportBrand').value,type=dialog.querySelector('#mbExportType').value;\n  const scope=dialog.querySelector('#mbExportScope').value;\n  const rows=products.filter(p=>{\n   if(brand&&p.brand!==brand||type&&p.category!==type)return false;\n   if(scope==='visible'&&((filter&&p.category!==filter)||![p.name,p.color,p.size,p.barcode,p.extra_code].join(' ').toLowerCase().includes(String(query||'').toLowerCase())))return false;\n   return true\n  });\n  if(!rows.length){error.textContent='Nenhuma peça corresponde aos filtros escolhidos.';return}\n  for(const p of rows){const k=p.model_id||[p.name,p.brand,p.category].join('|');if(!groupBy.has(k))groupBy.set(k,[]);groupBy.get(k).push(p)}\n  const labels=new Map(attrs),table=[fields.map(k=>csvCell(labels.get(k))).join(';')];\n  for(const group of groupBy.values()){\n   const sizeMap=new Map();let total=0;\n   for(const p of group){const q=Number(p.stock||0);sizeMap.set(p.size,(sizeMap.get(p.size)||0)+q);total+=q}\n   const allSizes=[...sizeMap].map(([size,qty])=>size+': '+qty).join(' | ');\n   for(const p of group){\n    const x={\n     name:p.name,category:p.category,brand:p.brand,barcode:p.barcode,extra_code:p.extra_code,\n     source_code:p.source_code,source_gtin:p.source_gtin,color:p.color,size:p.size,\n     stock:p.stock,reserved_stock:p.reserved_stock,available_stock:Math.max(0,Number(p.stock||0)-Number(p.reserved_stock||0)),\n     size_totals:allSizes,model_total:total,variations:group.length,\n     price:(Number(p.price||0)/100).toFixed(2).replace('.',','),\n     photo:[p.main_photo,p.photo].filter(Boolean).map(v=>new URL(v,location.origin).href).filter((v,i,a)=>a.indexOf(v)===i).join(' | ')\n    };\n    table.push(fields.map(k=>csvCell(x[k])).join(';'));\n   }\n  }\n  const csv='\\uFEFF'+table.join('\\r\\n')+'\\r\\n';\n  const basename=filename((document.title.includes('For Her')?'MB_For_Her':'MB_Dryfit')+'_modelos_'+new Date().toISOString().slice(0,10));\n  if(!dialog.querySelector('#mbExportImages').checked){download(new Blob([csv],{type:'text/csv;charset=utf-8;'}),basename+'.csv');info.textContent=groupBy.size+' modelos exportados.';return}\n  const photos=[...new Set(rows.flatMap(p=>[p.main_photo,p.photo].filter(Boolean)))];\n  if(photos.length>100){error.textContent='São '+photos.length+' imagens. Selecione menos modelos ou baixe primeiro o CSV sem fotos.';return}\n  button.disabled=true;button.textContent='Preparando ZIP…';\n  try{\n   const files=[{name:'modelos.csv',data:encoder.encode(csv)}];let bytesTotal=0,failed=0;\n   for(let i=0;i<photos.length;i++){\n    info.textContent='Preparando foto '+(i+1)+' de '+photos.length;\n    const u=new URL(photos[i],location.origin);\n    if(u.origin!==location.origin){failed++;continue}\n    const response=await fetch(u.href,{credentials:'same-origin'});\n    if(!response.ok){failed++;continue}\n    const bytes=new Uint8Array(await response.arrayBuffer());bytesTotal+=bytes.byteLength;\n    if(bytesTotal>85*1024*1024)throw Error('As imagens ultrapassam 85 MB. Escolha menos modelos por vez.');\n    const type=response.headers.get('Content-Type')||'';\n    const ext=type.includes('png')?'.png':type.includes('webp')?'.webp':'.jpg';\n    files.push({name:'fotos/'+String(i+1).padStart(3,'0')+'_'+filename(u.pathname.split('/').pop())+ext,data:bytes});\n   }\n   download(makeZip(files),basename+'.zip');\n   info.textContent='Arquivo com '+groupBy.size+' modelos e '+(files.length-1)+' fotos.'+(failed?' Algumas fotos estavam indisponíveis.':'');\n  }catch(e){error.textContent=e.message||'Erro ao preparar arquivos.'}\n  finally{button.disabled=false;button.textContent='Baixar seleção'}\n };\n dialog.showModal();\n}\n"
CSS = "\n/* Mobile-first adjustments to preserve readable cards and fields. */\nhtml,body{max-width:100%;overflow-x:clip}\n.shell,.shell>main,.workspace,#view,.heading,.toolbar,.grid,.form-grid,.panel,.card,.card .body{min-width:0}\n.workspace{max-width:100%;overflow-wrap:anywhere}\n.grid{grid-template-columns:repeat(auto-fit,minmax(min(100%,245px),1fr))}\n.heading{flex-wrap:wrap;gap:14px}\n.heading>div{min-width:0}.heading>div:last-child{max-width:100%}\n.toolbar{flex-wrap:wrap;gap:10px}\n.toolbar .search{max-width:100%;min-width:min(100%,260px)}\nimg,video,canvas{max-width:100%}\ndialog{max-width:calc(100vw - 20px)!important;max-height:calc(100dvh - 24px)!important;overflow:auto;overscroll-behavior:contain;border-radius:16px}\ndialog .form-grid,dialog .color-builder,dialog .size-grid{min-width:0}\ndialog .form-grid>*{min-width:0}\ndialog input:not([type=checkbox]):not([type=radio]),dialog textarea,dialog select{max-width:100%;min-width:0}\ndialog .actions{display:flex;flex-wrap:wrap;gap:10px}\n.mb-code-auto{display:flex!important;align-items:center;gap:12px;min-height:48px;padding:10px 14px;border-radius:12px;background:var(--bg,#f7f8f8);border:1px solid var(--line,#ddd)}\n.mb-code-auto input{width:20px;height:20px;flex-shrink:0;accent-color:var(--orange,#f97316)}\n.mb-code-select{display:none!important}\n.mb-delete-model{color:#ae382f!important}\n#mbExportModels{width:min(880px,calc(100vw - 20px));max-height:calc(100dvh - 24px);border:0;padding:clamp(15px,3vw,27px);box-shadow:0 22px 80px #0003}\n.mb-export-header,.mb-export-footer{display:flex;align-items:center;justify-content:space-between;gap:12px}\n.mb-export-header{margin-bottom:20px}\n.mb-export-header h2{font-size:20px;margin:0 0 7px}\n.mb-export-header p{font-size:12px;color:var(--muted,#666);margin:0}\n#mbExportModels h3{font-size:15px;margin:16px 0 12px}\n.mb-export-filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}\n.mb-export-filters label{display:grid;gap:7px;font-size:12px;font-weight:700;min-width:0}\n.mb-export-filters select{width:100%;min-height:42px;padding:8px;border:1px solid var(--line,#ddd);border-radius:9px;background:white}\n.mb-export-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.mb-export-fields label{display:flex;align-items:center;gap:9px;border:1px solid var(--line,#ddd);border-radius:9px;padding:10px 12px;font-size:12px;font-weight:500;min-width:0}\n.mb-export-fields input,.mb-export-zip input{flex:none;width:17px;height:17px;accent-color:var(--orange,#ff681e)}\n.mb-export-actions{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}\n.mb-export-zip{display:flex;align-items:center;gap:10px;font-size:12px;margin:14px 0}\n.mb-export-error{color:#b82c25;font-size:12px}\n.mb-export-footer{border-top:1px solid var(--line,#ddd);padding-top:16px}\n@media(max-width:1050px){.workspace{padding:clamp(12px,3vw,25px)}.topbar{padding:0 15px}.shell{grid-template-columns:minmax(175px,215px) minmax(0,1fr)}}\n@media(max-width:760px){.shell{display:block!important}.workspace{padding:14px!important}.topbar{min-height:60px;height:auto;gap:10px;padding:10px 13px!important}.topbar>*{min-width:0}\n .form-grid{grid-template-columns:1fr!important}.form-grid .wide{grid-column:auto!important}.grid{grid-template-columns:repeat(auto-fit,minmax(min(100%,215px),1fr))}\n .heading .primary,.heading .secondary{min-height:42px}.nav{max-width:100%;overflow-x:auto;scrollbar-width:thin}\n #modelModal{padding:16px!important}.color-builder-head{display:flex;flex-wrap:wrap;align-items:flex-start;gap:10px}\n .size-grid{grid-template-columns:repeat(auto-fit,minmax(min(100%,100px),1fr))!important}\n .model-section-heading{font-size:17px}.steps{overflow-x:auto;white-space:nowrap;padding-bottom:7px}\n .mb-export-filters{grid-template-columns:1fr 1fr}.mb-export-fields{grid-template-columns:1fr}\n}\n@media(max-width:460px){.workspace{padding:11px!important}.heading h2{font-size:20px}.grid{grid-template-columns:1fr}\n .mb-export-filters{grid-template-columns:1fr}#mbExportModels{padding:14px}\n .mb-export-header h2{font-size:18px}.mb-export-footer{flex-wrap:wrap}.mb-export-footer button{flex:1;min-width:120px}\n .card-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}\n .card-actions button{min-height:42px;min-width:0}\n .modal-head{align-items:flex-start}.modal-head>div{min-width:0}\n}\n"
for store in ("mb-dryfit","mb-for-her"):
    file=Path("stores")/store/"worker"/"page.html"
    s=file.read_text(encoding="utf-8")
    original=s
    # Only remove the obsolete shortcut buttons. Never delete saved archives.
    for anchor in [
        '<a class="secondary" href="/catalogo" target="_blank" rel="noopener">Ver vitrine ↗</a>',
        '<button class="secondary" onclick="openNexImportReport()">Importação Nex</button>',
        '<button class="secondary" type="button" onclick="showArchivedModels()">Arquivados</button>',
    ]:
        s=s.replace(anchor,"")
    new_button='<button class="secondary" type="button" onclick="mbOpenModelExport()">↓ Baixar informações</button>'
    if s.count('<button class="primary" onclick="openProduct()">＋ Novo modelo</button>')!=1:
        raise SystemExit("Product heading buttons changed: "+store)
    s=s.replace('<button class="primary" onclick="openProduct()">＋ Novo modelo</button>',new_button+'<button class="primary" onclick="openProduct()">＋ Novo modelo</button>',1)

    mode='<label>Códigos para novas variações<select name="barcode_mode" id="modelBarcodeMode"><option value="auto">Automático · gerar código</option><option value="manual">Manual · código do fornecedor</option></select><span class="help">Códigos já cadastrados permanecem fixos. Um código não pode identificar duas variações.</span></label>'
    checkbox='<label class="mb-code-auto"><input type="checkbox" id="mbAutomaticBarcode" checked> Código automático</label><select name="barcode_mode" id="modelBarcodeMode" class="mb-code-select" aria-label="Modo de geração de código"><option value="auto">Automático</option><option value="manual">Manual</option></select><span class="help">Marcado: o sistema gera o código. Desmarcado: informe manualmente os códigos para cada variação. Os códigos já cadastrados não mudam.</span>'
    if s.count(mode)!=1:raise SystemExit("Barcode selector changed: "+store)
    s=s.replace(mode,checkbox,1)
    control="$('#modelBarcodeMode').value=p?.barcode_mode||(typeof ownerBarcodePreference==='function'?ownerBarcodePreference():'auto');"
    if s.count(control)!=1:raise SystemExit("Barcode controller changed: "+store)
    s=s.replace(control,control+"$('#mbAutomaticBarcode').checked=$('#modelBarcodeMode').value==='auto';$('#mbAutomaticBarcode').onchange=()=>{$('#modelBarcodeMode').value=$('#mbAutomaticBarcode').checked?'auto':'manual';$('#modelBarcodeMode').dispatchEvent(new Event('change'))};",1)
    # Expose the audited model-management deletion dialog directly on the card.
    if s.count('<button data-single>Ajustar</button>')!=1:raise SystemExit("Card actions changed: "+store)
    s=s.replace('<button data-single>Ajustar</button>','<button data-single>Ajustar</button><button class="mb-delete-model" data-delete-model>Excluir modelo</button>',1)
    binder="card.querySelector('[data-single]').onclick=()=>openModel(p.id)"
    if s.count(binder)!=1:raise SystemExit("Card bind changed: "+store)
    s=s.replace(binder,binder+";card.querySelector('[data-delete-model]').onclick=()=>openModelDeletion(p.model_id||p.id)",1)
    if "</head>" not in s or "</body>" not in s:raise SystemExit("Invalid owner HTML: "+store)
    s=s.replace("</head>","<style>"+CSS+"</style></head>",1)
    s=s.replace("</body>","<script>"+UI_JS+"</script></body>",1)
    if original==s:raise SystemExit("No changes produced: "+store)
    file.write_text(s,encoding="utf-8")
    print("Owner export, code checkbox, deletion shortcut and mobile UI:",store)
